package controller;

import constants.Constants;
import constants.Message;
import constants.ProgrammingLanguage;
import dto.ResponseDTO;
import dto.StudentDTO;
import java.util.List;
import repository.StudentRepository;
import service.StudentService;
import view.StudentView;

/**
 * Nhan phieu DTO tu Main. Controller goi Repository de tim/them/xoa (CRUD),
 * goi Service de xu ly nghiep vu, roi dua ket qua cho View in.
 *
 * @author CuongThai Academy
 */
public class StudentController {

    // Kho sinh vien (CRUD)
    private StudentRepository studentRepository;

    // Nghiep vu sinh vien
    private StudentService studentService;

    // Man hinh in ket qua
    private StudentView studentView;

    // Tao kho, service, view va nap du lieu mau
    public StudentController() {
        this.studentRepository = new StudentRepository();
        this.studentService = new StudentService();
        this.studentView = new StudentView();

        // Nap du lieu mau; loi thi in ra
        try {
            generateStudent();
        } catch (Exception e) {
            // Du lieu mau bi trung thi bao loi
            studentView.setMessage(e.getMessage());
            studentView.display();
        }
    }

    // Them 1 lan hoc cho sinh vien, bao ket qua; tra ve so sinh vien dang co
    // (Main dua vao so nay de biet da du 10 sinh vien chua — khong phai goi them ham dem)
    public int addStudent(StudentDTO studentDTO) {
        // Them duoc thi bao thanh cong
        try {
            saveEnrollment(studentDTO);
            studentView.setMessage(Message.SUCCESS_ADD_MESSAGE);
        } catch (Exception e) {
            // Trung ID cua nguoi khac hoac trung lan hoc thi bao loi
            studentView.setMessage(e.getMessage());
        }

        studentView.display();
        return studentRepository.getSize();
    }

    // In cac ban ghi cua sinh vien theo ID, tra ve so ban ghi (0 neu khong co)
    public int findStudentById(StudentDTO studentDTO) {
        List<ResponseDTO> recordList
                = studentService.toRecordList(studentRepository.findById(studentDTO.getId()));

        // Khong co ID thi bao khong tim thay, co thi in bang
        if (recordList.isEmpty()) {
            studentView.setMessage(String.format(Message.ERROR_CANNOT_FOUND,
                    studentDTO.getId()));
        } else {
            // Co ban ghi thi in de nguoi dung chon so thu tu
            studentView.setResponseList(recordList);
        }

        studentView.display();
        return recordList.size();
    }

    // Tim theo ten va in bang da sap xep
    public void findAndSort(StudentDTO studentDTO) {
        List<ResponseDTO> resultList
                = studentService.sortByName(
                        studentRepository.findByName(studentDTO.getStudentName()));

        // Khong tim thay thi bao, nguoc lai in bang
        if (resultList.isEmpty()) {
            studentView.setMessage(String.format(Message.ERROR_NAME_NOT_FOUND,
                    studentDTO.getStudentName()));
        } else {
            // Co ket qua thi in bang
            studentView.setResponseList(resultList);
        }

        studentView.display();
    }

    // Sua (U) hoac xoa (D) ban ghi so no cua sinh vien, bao ket qua
    public void updateOrDeleteStudent(StudentDTO studentDTO) {
        // Lam viec nguoi dung chon; loi thi bao loi
        try {
            // U thi sua, D thi xoa
            if (studentDTO.getAction().equalsIgnoreCase(Constants.UPDATE)) {
                updateStudent(studentDTO);
                studentView.setMessage(Message.SUCCESS_UPDATE_MESSAGE);
            } else {
                // D: xoa ban ghi
                deleteStudent(studentDTO);
                studentView.setMessage(Message.SUCCESS_DELETE_MESSAGE);
            }
        } catch (Exception e) {
            // Trung lan hoc hoac khong co ban ghi thi bao loi
            studentView.setMessage(e.getMessage());
        }

        studentView.display();
    }

    // In bao cao, hoac bao danh sach rong
    public void report() {
        // Rong thi bao rong, nguoc lai in bao cao
        if (studentRepository.isEmpty()) {
            studentView.setMessage(Message.ERROR_EMPTY);
        } else {
            // Co du lieu thi in bao cao
            studentView.setResponseList(
                    studentService.buildReport(studentRepository.getAllStudents()));
            studentView.setReport(true);
        }

        studentView.display();
    }

    // Sua hoc ky + mon: kho tim sinh vien, Service kiem trung roi sua
    private void updateStudent(StudentDTO studentDTO) throws Exception {
        studentService.updateEnrollment(studentRepository.findById(studentDTO.getId()),
                studentDTO);
    }

    // Xoa ban ghi: Service xoa lan hoc; sinh vien het lan hoc thi kho xoa sinh vien
    private void deleteStudent(StudentDTO studentDTO) throws Exception {
        // Het lan hoc thi xoa ca sinh vien khoi kho
        if (studentService.removeEnrollment(studentRepository.findById(studentDTO.getId()),
                studentDTO)) {
            studentRepository.deleteStudent(studentRepository.findById(studentDTO.getId()));
        }
    }

    // Nap 9 sinh vien mau (13 lan hoc) trong Constants de thu nhanh
    private void generateStudent() throws Exception {
        // Moi dong mau: ID, ten, hoc ky, so mon (1 Java, 2 .Net, 3 C/C++)
        for (String[] rowArray : Constants.SAMPLE_STUDENT_ARRAY) {
            // Them tung dong mau vao kho
            saveEnrollment(new StudentDTO(rowArray[Constants.SAMPLE_ID_INDEX],
                    rowArray[Constants.SAMPLE_NAME_INDEX],
                    rowArray[Constants.SAMPLE_SEMESTER_INDEX],
                    ProgrammingLanguage.getByNumber(
                            Integer.parseInt(rowArray[Constants.SAMPLE_COURSE_INDEX]))));
        }
    }

    // Them 1 lan hoc: tim trong kho, Service kiem + them, roi luu lai vao kho
    private void saveEnrollment(StudentDTO studentDTO) throws Exception {
        // Kho tim theo ID, Service them lan hoc, kho luu (sinh vien moi thi them)
        studentRepository.save(studentService.addEnrollment(
                studentRepository.findById(studentDTO.getId()), studentDTO));
    }
}

