package main;

import constants.Constants;
import constants.Message;
import constants.ProgrammingLanguage;
import controller.StudentController;
import dto.StudentDTO;
import java.util.Scanner;
import utils.Validation;

/**
 * Chay chuong trinh: in menu, doc va kiem moi o nhap, roi goi Controller.
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Ngan khong cho tao doi tuong Main (Main chi co ham static)
    private Main() {
    }

    // Diem bat dau: lap menu den khi chon 5
    public static void main(String[] args) {
        StudentController studentController = new StudentController();
        Scanner sc = new Scanner(System.in);
        int choice = 0;

        // Lap lai menu sau moi chuc nang
        while (true) {
            System.out.println(Message.MENU_HEADER.concat(Message.MENU_BODY));
            choice = inputChoice(sc);

            // Chay chuc nang nguoi dung chon
            switch (choice) {
                // 1: tao sinh vien
                case Constants.MENU_CREATE:
                    processAdd(sc, studentController);
                    break;

                // 2: tim theo ten va sap xep
                case Constants.MENU_FIND_SORT:
                    processFind(sc, studentController);
                    break;

                // 3: tim theo ID roi sua hoac xoa
                case Constants.MENU_UPDATE_DELETE:
                    processUpdateDelete(sc, studentController);
                    break;

                // 4: bao cao
                case Constants.MENU_REPORT:
                    studentController.report();
                    break;

                // 5: thoat chuong trinh
                case Constants.MENU_EXIT:
                    System.out.println(Message.EXIT_MESSAGE);
                    return;

                // Khong xay ra: inputChoice chi tra ve 1 den 5
                default:
                    break;
            }
        }
    }

    // Tao sinh vien; tu khi du 10 sinh vien thi hoi Y/N sau moi lan nhap
    private static void processAdd(Scanner sc, StudentController studentController) {
        StudentDTO studentDTO = null;
        int studentCount = 0;

        // Lap nhap tung sinh vien den khi chon N (chi hoi khi da du 10 sinh vien)
        while (true) {
            studentDTO = inputStudent(sc);
            studentCount = studentController.addStudent(studentDTO);

            // Du 10 sinh vien tro len ma chon N thi ve menu
            if ((studentCount >= Constants.MIN_STUDENTS) &&
                    !inputYesNo(sc).equalsIgnoreCase(Constants.YES)) {
                break;
            }
        }
    }

    // Nhap du 4 o cua 1 lan hoc: ID, ten, hoc ky, mon (moi o sai thi hoi lai o do)
    private static StudentDTO inputStudent(Scanner sc) {
        StudentDTO studentDTO = new StudentDTO();

        studentDTO.setId(inputId(sc));
        studentDTO.setStudentName(inputName(sc));
        studentDTO.setSemester(inputSemester(sc, Message.INPUT_SEMESTER));
        studentDTO.setCourseName(inputCourse(sc));
        return studentDTO;
    }

    // Nhap ten (hoac 1 phan ten) roi tim va sap xep
    private static void processFind(Scanner sc, StudentController studentController) {
        StudentDTO studentDTO = new StudentDTO();

        studentDTO.setStudentName(inputName(sc));
        studentController.findAndSort(studentDTO);
    }

    // Tim sinh vien theo ID, chon ban ghi, roi sua (U) hoac xoa (D)
    private static void processUpdateDelete(Scanner sc, StudentController studentController) {
        StudentDTO studentDTO = new StudentDTO();
        int recordCount = 0;

        studentDTO.setId(inputId(sc));
        recordCount = showRecords(studentController, studentDTO);

        // Khong co ID thi Controller da bao loi, ve menu
        if (recordCount == 0) {
            return;
        }

        studentDTO.setNo(inputRecordNo(sc, recordCount));
        studentDTO.setAction(inputUpdateDelete(sc));

        // Chon U thi nhap them hoc ky + mon moi
        if (studentDTO.getAction().equalsIgnoreCase(Constants.UPDATE)) {
            studentDTO.setSemester(inputSemester(sc, Message.EDIT_SEMESTER));
            studentDTO.setCourseName(inputCourse(sc));
        }

        studentController.updateOrDeleteStudent(studentDTO);
    }

    // Kiem truoc (pre-check): in cac ban ghi cua ID de nguoi dung chon, tra ve so ban ghi
    private static int showRecords(StudentController studentController, StudentDTO studentDTO) {
