/**
 * Model 1 sinh vien: ID, ten va danh sach cac lan hoc (hoc ky + mon).
 *
 * @author CuongThai Academy
 */
public class Student {

    // ID sinh vien, vi du S1
    private String id;

    // Ten sinh vien
    private String studentName;

    // Cac lan hoc cua sinh vien (thay cho semester + courseName don le)
    private List<Enrollment> enrollmentList;

    // Tao sinh vien rong (JavaBean)
    public Student() {
        this.enrollmentList = new ArrayList<>();
    }

    // Tao sinh vien moi chua co lan hoc nao
    public Student(String id, String studentName) {
        this.id = id;
        this.studentName = studentName;
        this.enrollmentList = new ArrayList<>();
    }

    // Tra ve ID
    public String getId() {
        return id;
    }

    // Gan ID
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ten
    public String getStudentName() {
        return studentName;
    }

    // Gan ten
    public void setStudentName(String studentName) {
        this.studentName = studentName;
    }

    // Tra ve danh sach lan hoc
    public List<Enrollment> getEnrollmentList() {
        return enrollmentList;
    }

    // Them 1 lan hoc; trung hoc ky + mon thi bao loi
    public void addEnrollment(Enrollment enrollment) throws Exception {
        // Da co lan hoc giong het thi khong them
        if (isDuplicated(enrollment, -1)) {
            throw new Exception(Message.ERROR_DUPLICATE);
        }

        enrollmentList.add(enrollment);
    }

    // Kiem da co lan hoc trung hoc ky + mon chua (bo qua vi tri ignoreIndex khi dang sua)
    public boolean isDuplicated(Enrollment newEnrollment, int ignoreIndex) {
        Enrollment enrollment = null;

        // Duyet tung lan hoc
        for (int i = 0; i < enrollmentList.size(); i++) {
            enrollment = enrollmentList.get(i);

            // Trung hoc ky (khong phan biet hoa thuong) va trung mon, khac vi tri dang sua
            if ((i != ignoreIndex) &&
                    (enrollment.getSemester().equalsIgnoreCase(newEnrollment.getSemester())) &&
                    (enrollment.getCourse().equals(newEnrollment.getCourse()))) {
                return true;
            }
        }

        return false;
    }
}

