package service;

import constants.Constants;
import constants.Message;
import dto.ResponseDTO;
import dto.StudentDTO;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import model.Enrollment;
import model.Student;

/**
 * Nghiep vu: them lan hoc, sap xep theo ten, sua/xoa ban ghi, dem bao cao.
 * Service CHI xu ly du lieu Controller dua vao — khong tao, khong goi kho du lieu.
 * Moi thao tac tim/them/xoa trong kho (CRUD) do Controller goi lop repository lam.
 *
 * @author CuongThai Academy
 */
public class StudentService {

    // Them lan hoc. student = sinh vien Controller tim trong kho (null neu chua co ID).
    // Tra ve sinh vien (moi tao hoac da co) de Controller luu vao kho neu la sinh vien moi.
    public Student addEnrollment(Student student, StudentDTO studentDTO) throws Exception {
        // Chua co ID thi tao sinh vien moi; co roi ma khac ten thi bao loi
        if (student == null) {
            student = new Student(studentDTO.getId(), studentDTO.getStudentName());
        } else if (!student.getStudentName().equalsIgnoreCase(studentDTO.getStudentName())) {
            // ID da co nhung ten khac thi bao ID thuoc ve nguoi khac
            throw new Exception(String.format(Message.ERROR_DUPLICATE_ID,
                    student.getStudentName()));
        }

        student.addEnrollment(new Enrollment(studentDTO.getSemester(),
                studentDTO.getCourseName()));

        return student;
    }

    // Doi cac lan hoc cua 1 sinh vien thanh cac dong bang (rong neu khong co sinh vien)
    public List<ResponseDTO> toRecordList(Student student) {
        // Khong co sinh vien thi tra danh sach rong
        if (student == null) {
            return new ArrayList<>();
        }

        return convertToResponse(student);
    }

    // Danh sach sinh vien tim duoc -> bang sap xep theo ten bang Comparator, danh so lai
    public List<ResponseDTO> sortByName(List<Student> studentList) {
        List<ResponseDTO> resultList = new ArrayList<>();

        // Doi tung sinh vien tim duoc thanh cac dong bang
        for (Student student : studentList) {
            resultList.addAll(convertToResponse(student));
        }

        // Sap xep theo ten: ghi de ham compare() cua Comparator nhu de yeu cau
        Collections.sort(resultList, new Comparator<ResponseDTO>() {
            // So 2 dong theo ten sinh vien
            @Override
            public int compare(ResponseDTO first, ResponseDTO second) {
                return first.getStudentName().compareTo(second.getStudentName());
            }
        });

        // Danh so thu tu lai sau khi sap xep
        for (int i = 0; i < resultList.size(); i++) {
            resultList.get(i).setNo(i + 1);
        }

        return resultList;
    }

    // Sua hoc ky + mon cua ban ghi so no cua sinh vien; trung voi ban ghi khac thi bao loi
    public void updateEnrollment(Student student, StudentDTO studentDTO) throws Exception {
        Enrollment enrollment = null;
        Enrollment newEnrollment = new Enrollment(studentDTO.getSemester(),
                studentDTO.getCourseName());

        checkRecord(student, studentDTO);

        // Hoc ky + mon moi trung voi ban ghi khac cua chinh sinh vien thi bao loi
        if (student.isDuplicated(newEnrollment, studentDTO.getNo() - 1)) {
            throw new Exception(Message.ERROR_DUPLICATE);
        }

        enrollment = student.getEnrollmentList().get(studentDTO.getNo() - 1);
        enrollment.setSemester(newEnrollment.getSemester());
        enrollment.setCourse(newEnrollment.getCourse());
    }

    // Xoa ban ghi so no. Tra ve true neu sinh vien khong con lan hoc nao
    // (luc do Controller goi kho de xoa sinh vien).
    public boolean removeEnrollment(Student student, StudentDTO studentDTO) throws Exception {
        checkRecord(student, studentDTO);

        student.getEnrollmentList().remove(studentDTO.getNo() - 1);

        return student.getEnrollmentList().isEmpty();
    }

    // Bao cao: moi dong = ten | mon | so lan hoc mon do (giu thu tu nhap)
    public List<ResponseDTO> buildReport(List<Student> studentList) {
        List<ResponseDTO> reportList = new ArrayList<>();
        Map<String, Integer> reportMap = new LinkedHashMap<>();
        String key = "";
        String[] partArray = null;
        ResponseDTO responseDTO = null;

        // Dem so lan hoc theo cap (ten, mon)
        for (Student student : studentList) {
            // Moi lan hoc cong 1 vao cap (ten, mon) cua no
            for (Enrollment enrollment : student.getEnrollmentList()) {
                key = String.format(Constants.REPORT_KEY_FORMAT, student.getStudentName(),
                        enrollment.getCourse().getName());
                reportMap.put(key, reportMap.getOrDefault(key, 0) + 1);
            }
        }

        // Doi tung cap (ten, mon) thanh 1 dong bao cao
        for (Map.Entry<String, Integer> entry : reportMap.entrySet()) {
            partArray = entry.getKey().split(Constants.REPORT_KEY_SEPARATOR);
            responseDTO = new ResponseDTO();
            responseDTO.setStudentName(partArray[0]);
            responseDTO.setCourseName(partArray[1]);
            responseDTO.setTotal(entry.getValue());
            reportList.add(responseDTO);
        }

        return reportList;
    }

    // Kiem sinh vien ton tai va so thu tu ban ghi hop le; sai thi bao loi
    private void checkRecord(Student student, StudentDTO studentDTO) throws Exception {
        // Khong co sinh vien hoac so ban ghi ngoai khoang thi bao khong tim thay
        if ((student == null) || (studentDTO.getNo() < Constants.RECORD_MIN) ||
                (studentDTO.getNo() > student.getEnrollmentList().size())) {
            throw new Exception(String.format(Message.ERROR_CANNOT_FOUND, studentDTO.getId()));
        }
    }

    // Doi cac lan hoc cua 1 sinh vien thanh cac dong bang, danh so tu 1
    private List<ResponseDTO> convertToResponse(Student student) {
        List<ResponseDTO> rowList = new ArrayList<>();
        ResponseDTO responseDTO = null;
        int no = 1;

        // Moi lan hoc la 1 dong
        for (Enrollment enrollment : student.getEnrollmentList()) {
            responseDTO = new ResponseDTO();
            responseDTO.setNo(no);
            responseDTO.setId(student.getId());
            responseDTO.setStudentName(student.getStudentName());
            responseDTO.setSemester(enrollment.getSemester());
            responseDTO.setCourseName(enrollment.getCourse().getName());
            rowList.add(responseDTO);
            no++;
        }

        return rowList;
    }
}

