package utils;

import constants.Constants;
import constants.Message;

/**
 * Kiem tra chu nguoi dung go vao. Sai thi nem Exception kem cau bao loi cu the.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Ngan khong cho tao doi tuong Validation
    private Validation() {
    }

    // Doi chu thanh so nguyen va kiem so nam trong [min, max]
    public static int getInt(String input, int min, int max) throws Exception {
        int number = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            number = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong thi bao phai nhap so nguyen
            throw new Exception(Message.ERROR_NOT_INTEGER);
        }

        // So ngoai khoang thi bao khoang dung
        if ((number < min) || (number > max)) {
            throw new Exception(String.format(Message.ERROR_INTEGER_RANGE, min, max));
        }

        return number;
    }

    // Kiem ID: chu S roi toi so, vi du S1
    public static String checkId(String input) throws Exception {
        String text = input.trim();

        // Sai dang thi bao loi ID
        if (!text.matches(Constants.REGEX_ID)) {
            throw new Exception(Message.ERROR_ID);
        }

        return text;
    }

    // Kiem ten: chu cai khong dau, so, dau cach, khong rong
    public static String checkName(String input) throws Exception {
        String text = input.trim();

        // Rong hoac co ky tu la thi bao loi ten
        if (!text.matches(Constants.REGEX_NAME)) {
            throw new Exception(Message.ERROR_NAME);
        }

        return text;
    }

    // Kiem hoc ky: chu cai khong dau, so, khong rong
    public static String checkSemester(String input) throws Exception {
        String text = input.trim();

        // Rong hoac co ky tu la thi bao loi hoc ky
        if (!text.matches(Constants.REGEX_NAME)) {
            throw new Exception(Message.ERROR_SEMESTER);
        }

        return text;
    }

    // Kiem chon Y hoac N
    public static String checkYesNo(String input) throws Exception {
        String text = input.trim();

        // Khong phai Y/N thi bao loi
        if (!text.matches(Constants.REGEX_YN)) {
            throw new Exception(Message.ERROR_YN);
        }

        return text;
    }

    // Kiem chon U hoac D
    public static String checkUpdateDelete(String input) throws Exception {
        String text = input.trim();

        // Khong phai U/D thi bao loi
        if (!text.matches(Constants.REGEX_UD)) {
            throw new Exception(Message.ERROR_UD);
        }

        return text;
    }
}

