    private String message;

    // true: in dang bao cao "Ten | Mon | Tong"; false: in bang sinh vien
    private boolean report;

    // Tao View rong
    public StudentView() {
        responseList = new ArrayList<>();
        message = "";
        report = false;
    }

    // Controller dua cac dong can in vao View
    public void setResponseList(List<ResponseDTO> responseList) {
        this.responseList = responseList;
    }

    // Controller dua cau thong bao vao View
    public void setMessage(String message) {
        this.message = message;
    }

    // Controller chon in dang bao cao (true) hay bang sinh vien (false)
    public void setReport(boolean report) {
        this.report = report;
    }

    // In ket qua cua 1 luong, roi xoa trang thai de luong sau bat dau sach
    public void display() {
        // Co cau thong bao thi chi in cau do
        if (!message.isEmpty()) {
            System.out.println(message);
        } else if (report) {
            // Bao cao: tieu de roi tung dong "Ten | Mon | Tong"
            System.out.println(Message.TITLE_REPORT);
            printRows();
        } else {
            // Bang sinh vien: dong tieu de cot roi tung dong
            System.out.println(String.format(Constants.TABLE_FORMAT, Message.COLUMN_NO,
                    Message.COLUMN_NAME, Message.COLUMN_SEMESTER, Message.COLUMN_COURSE));
            printRows();
        }

        message = "";
        report = false;
    }

    // In tung dong dang giu (bao cao hay bang tuy che do)
    private void printRows() {
        // Moi dong 1 lan println
        for (ResponseDTO row : responseList) {
            // Bao cao dung toReportString, bang dung toString
            if (report) {
                System.out.println(row.toReportString());
            } else {
                // Bang sinh vien: No, ten, hoc ky, mon
                System.out.println(row.toString());
            }
        }
    }
}

